import net.runelite.api.gameval.ItemID;
import static com.escapecrystalnotify.EscapeCrystalNotifyCrystalDefaults.*;

class EscapeCrystalNotifyCrystal3d
{
	private final Client client;
	private final EscapeCrystalNotifyConfig config;
	private RuneLiteObject crystal;
	private Model model;
	private EscapeCrystalNotifyCrystalFill crystalFill;
	private int modelSize;
	private short modelColor;
	private long lastFrame;
	private long nextModelAttempt;
	private double rotation;
	private double bobPhase;
	private boolean carried, active, notifyLocation;
	private double inactivityFraction = 1, hitpointsFraction = 1, prayerFraction = 1;
	private Color convertedFrom;
	private short convertedColor;
	private final EscapeCrystalNotifyCrystalClearance clearance = new EscapeCrystalNotifyCrystalClearance();

	@Inject
	EscapeCrystalNotifyCrystal3d(Client client, EscapeCrystalNotifyConfig config)
	{
		this.client = client;
		this.config = config;
	}

	void updateState(boolean carried, boolean active, boolean notifyLocation, int remainingTicks, int totalTicks)
	{
		this.carried = carried;
		this.active = active;
		this.notifyLocation = notifyLocation;
		inactivityFraction = EscapeCrystalNotifyCrystalFill.fraction(carried, active, remainingTicks, totalTicks);
		hitpointsFraction = resourceFraction(Skill.HITPOINTS);
		prayerFraction = resourceFraction(Skill.PRAYER);
	}

	private double resourceFraction(Skill skill)
	{
		return EscapeCrystalNotifyCrystalFill.fraction(client.getBoostedSkillLevel(skill), client.getRealSkillLevel(skill));
	}

	private double fillFraction(EscapeCrystalNotifyConfig.Crystal3dFillMode mode)
	{
		switch (mode)
		{
			case INACTIVITY_TIME: return inactivityFraction;
			case HITPOINTS: return hitpointsFraction;
			case PRAYER_POINTS: return prayerFraction;
			default: return 1;
		}
	}

	void update()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			reset();
			return;
		}
		if (!config.enableCrystal3d())
		{
			reset();
			return;
		}
		if (!config.crystal3dDisplayEverywhere() && !notifyLocation)
		{
			hide();
			return;
		}
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			reset();
			return;
		}

		LocalPoint location = player.getLocalLocation();
		WorldView worldView = player.getWorldView();
		if (!EscapeCrystalNotifySceneBounds.contains(location, worldView))
		{
			reset();
			return;
		}

		EscapeCrystalNotifyConfig.Crystal3dDisplayStyle placement = config.crystal3dDisplayStyle();
		boolean leftOfHead = placement == EscapeCrystalNotifyConfig.Crystal3dDisplayStyle.LEFT_OF_HEAD;
		boolean besideHead = placement != EscapeCrystalNotifyConfig.Crystal3dDisplayStyle.ABOVE_HEAD;
		int requestedSize = !besideHead ? config.crystal3dSize()
			: leftOfHead ? config.crystal3dLeftSize() : config.crystal3dRightSize();
		int bobHeight = config.crystal3dBobHeight();
		if (besideHead)
		{
			requestedSize = (int) Math.round(requestedSize * SMALL_STYLE_SCALE);
			bobHeight = (int) Math.round(bobHeight * SMALL_STYLE_SCALE);
		}
		Color color = carried && active ? config.crystal3dActiveColor() : config.crystal3dInactiveColor();
		if (!color.equals(convertedFrom))
		{
			convertedColor = JagexColor.rgbToHSL(color.getRGB(), COLOR_BRIGHTNESS);
			convertedFrom = color;
		}
		short requestedColor = convertedColor;
		long now = System.nanoTime();
		if (model == null || modelSize != requestedSize || modelColor != requestedColor)
		{
			// Cache assets can be temporarily unavailable; avoid trying to load them every frame.
			if (now >= nextModelAttempt)
			{
				Model replacement = buildModel(requestedSize, requestedColor);
				if (replacement == null)
				{
					nextModelAttempt = now + MODEL_RETRY_NANOS;
				}
				else
				{
					model = replacement;
					crystalFill = null;
					modelSize = requestedSize;
					modelColor = requestedColor;
					if (crystal != null) crystal.setModel(model);
					nextModelAttempt = 0;
				}
			}
			if (model == null)
			{
				return;
			}
		}

		EscapeCrystalNotifyConfig.Crystal3dFillMode fillMode = config.crystal3dFillMode();
		if (fillMode != EscapeCrystalNotifyConfig.Crystal3dFillMode.DISABLED)
		{
			if (crystalFill == null) crystalFill = new EscapeCrystalNotifyCrystalFill(model);
			crystalFill.apply(fillFraction(fillMode));
		}
		else if (crystalFill != null)
		{
			crystalFill.apply(1);
		}

		if (crystal == null)
		{
			crystal = client.createRuneLiteObject();
			crystal.setModel(model);
		}
		// setLocation also sets terrain height, and re-registers when moving between world views.
		crystal.setLocation(location, worldView.getPlane());
		double elapsed = lastFrame == 0 ? 0 : Math.min((now - lastFrame) / 1_000_000_000.0, MAX_FRAME_SECONDS);
		lastFrame = now;
		int period = config.crystal3dSpinSeconds();
		if (period > 0)
		{
			rotation = (rotation + elapsed * FULL_TURN / period) % FULL_TURN;
		}
		int bob = 0;
		if (bobHeight > 0)
		{
			bobPhase = (bobPhase + elapsed * Math.PI * 2 / BOB_PERIOD_SECONDS) % (Math.PI * 2);
			bob = (int) Math.round(Math.sin(bobPhase) * bobHeight);
		}
		int lift;
		if (besideHead)
		{
			clearance.clear();
			// Use the rendered facing direction and the player's ground height, not the camera or offset tile.
			int distance = Math.max(0, Math.min(MAX_SIDE_OFFSET,
				leftOfHead ? config.crystal3dLeftOffset() : config.crystal3dSideOffset()));
			LocalPoint side = EscapeCrystalNotifyCrystalSidePosition.position(location, player.getCurrentOrientation(),
				leftOfHead ? -distance : distance,
				leftOfHead ? config.crystal3dLeftForwardOffset() : config.crystal3dForwardOffset());
			if (!EscapeCrystalNotifySceneBounds.contains(side, worldView))
			{
				if (crystal.isActive()) crystal.setActive(false);
				return;
			}
			crystal.setX(side.getX());
			crystal.setY(side.getY());
			lift = player.getLogicalHeight()
				+ (leftOfHead ? config.crystal3dLeftHeight() : config.crystal3dSideHeight()) + bob;
		}
		else if (config.crystal3dAutomaticClearance())
		{
			// Use the installed size while a replacement model is waiting for cache assets.
			int radius = (int) Math.ceil(modelSize * MODEL_WIDTH_RATIO / 2 * Math.sqrt(2));
			int halfHeight = (int) Math.ceil(modelSize / 2.0) + bobHeight;
			int safeLift = clearance.lift(client, player, location, crystal.getZ(), radius, halfHeight,
				config.crystal3dClearancePadding(), now, elapsed);
			if (safeLift < 0)
			{
				// Give game overheads priority when the camera leaves no safe room for the crystal.
				if (crystal.isActive()) crystal.setActive(false);
				return;
			}
			lift = safeLift + bob;
		}
		else
		{
			clearance.clear();
			// Negative Z is upwards; the centered model needs half its height above the manual gap.
			lift = player.getLogicalHeight() + config.crystal3dHeight() + modelSize / 2 + bob;
		}
		crystal.setZ(crystal.getZ() - lift);
		crystal.setOrientation((int) rotation);
		if (!crystal.isActive())
		{
			crystal.setActive(true);
		}
	}

	private void hide()
	{
		if (crystal != null && crystal.isActive()) crystal.setActive(false);
		lastFrame = 0;
		clearance.clear();
	}

	/** Release scene resources; display metrics are refreshed by the next game tick. */
	void reset()
	{
		hide();
		crystal = null;
		model = null;
		crystalFill = null;
		nextModelAttempt = 0;
		rotation = 0;
		bobPhase = 0;
	}

	private Model buildModel(int size, short color)
	{
		int modelId = client.getItemDefinition(ItemID.TOB_TELEPORT).getInventoryModel();
		ModelData source = client.loadModelData(modelId);
		if (source == null)
		{
			return null;
		}
		// All edited arrays must be private: loadModelData shares its arrays with the game cache.
		ModelData data = source.shallowCopy().cloneVertices().cloneColors();
		normalizeAxis(data.getVerticesX(), data.getVerticesCount(), size * MODEL_WIDTH_RATIO);
		normalizeAxis(data.getVerticesY(), data.getVerticesCount(), size);
		normalizeAxis(data.getVerticesZ(), data.getVerticesCount(), size * MODEL_WIDTH_RATIO);
		Arrays.fill(data.getFaceColors(), color);
		if (data.getFaceTextures() != null)
		{
			// Untextured models have no texture array; RuneLite's cloneTextures requires one.
			data.cloneTextures();
			Arrays.fill(data.getFaceTextures(), (short) -1);
		}
		if (data.getFaceTransparencies() != null)
		{
			data.cloneTransparencies();
			Arrays.fill(data.getFaceTransparencies(), (byte) 0);
		}
		return data.light();
	}

	static void normalizeAxis(float[] vertices, int count, float extent)
	{
		if (count == 0)
		{
			return;
		}
		float min = vertices[0];
		float max = min;
		for (int i = 1; i < count; i++)
		{
			min = Math.min(min, vertices[i]);
			max = Math.max(max, vertices[i]);
		}
		float center = (min + max) / 2;
		float scale = max == min ? 0 : extent / (max - min);
		for (int i = 0; i < count; i++)
		{
			vertices[i] = (vertices[i] - center) * scale;
		}
	}
}

package com.escapecrystalnotify;

import java.awt.Shape;
import static com.escapecrystalnotify.EscapeCrystalNotifyCrystalDefaults.*;
import java.util.function.IntFunction;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

class EscapeCrystalNotifyCrystalClearance
{
	private double reservedPixels;
	private long holdUntil;
	private int previousLift = -1;

	int lift(Client client, Player player, LocalPoint location, int groundZ, int radius,
		int halfHeight, int padding, long now, double elapsed)
	{
		int logicalHeight = player.getLogicalHeight();
		Point head = Perspective.localToCanvas(client, location.getWorldView(), location.getX(),
			location.getY(), groundZ - logicalHeight - HEAD_ANCHOR_OFFSET);
		if (head == null)
		{
			return -1;
		}
		boolean hint = client.getHintArrowPlayer() == player;
		WorldPoint hintPoint = client.getHintArrowPoint();
		if (!hint && hintPoint != null)
		{
			WorldPoint playerPoint = player.getWorldLocation();
			hint = playerPoint != null && hintPoint.getPlane() == playerPoint.getPlane()
				&& Math.abs(hintPoint.getX() - playerPoint.getX()) <= HINT_DISTANCE_TILES
				&& Math.abs(hintPoint.getY() - playerPoint.getY()) <= HINT_DISTANCE_TILES;
		}
		String text = player.getOverheadText();
		int pixels = overheadPixels(player.getSkullIcon() != -1, player.getOverheadIcon() != null,
			player.getHealthRatio() >= 0, hint, text != null && !text.isEmpty());
		int held = reserve(pixels, now, elapsed);
		int targetBottom = head.getY() - held - padding;
		// Also clear parts of the rendered actor model extending above the usual logical head height.
		Shape actorHull = player.getConvexHull();
		if (actorHull != null)
		{
			targetBottom = Math.min(targetBottom, actorHull.getBounds().y - padding);
		}
		int viewportTop = client.getViewportYOffset() + VIEWPORT_EDGE_MARGIN;
		int viewportBottom = client.getViewportYOffset() + client.getViewportHeight() - VIEWPORT_EDGE_MARGIN;
		int viewportLeft = client.getViewportXOffset() + VIEWPORT_EDGE_MARGIN;
		int viewportRight = client.getViewportXOffset() + client.getViewportWidth() - VIEWPORT_EDGE_MARGIN;
		// Include the entire rotational envelope and both extremes of the bob, not only the bottom tip.
		return solve(logicalHeight + halfHeight, targetBottom,
			viewportLeft, viewportTop, viewportRight, viewportBottom,
			centerLift -> bounds(client, location, groundZ - centerLift, radius, halfHeight));
	}

	static int overheadPixels(boolean skull, boolean prayer, boolean health, boolean hint, boolean chat)
	{
		// Public Actor API exposes health presence, not the full bar stack or final sprite rectangles.
		// Empty slots must not lift the crystal. The grace period below handles prayer flicking.
		// Hitsplats sit below this head anchor; custom name overlays can use the padding setting.
		int pixels = 0;
		if (health) pixels += HEALTH_PIXELS; // Space for stacked standard health/status bars.
		if (skull) pixels += SKULL_PIXELS;
		if (prayer) pixels += PRAYER_PIXELS;
		if (hint) pixels += HINT_PIXELS; // Player-target and nearby coordinate hint arrows, including blinking.
		if (chat) pixels += CHAT_PIXELS; // Text height plus standard wave/scroll effects.
		return pixels;
	}

	int reserve(int requested, long now, double elapsed)
	{
		if (requested >= reservedPixels)
		{
			reservedPixels = requested;
			holdUntil = now + CLEARANCE_HOLD_NANOS;
		}
		else if (now >= holdUntil)
		{
			reservedPixels = Math.max(requested, reservedPixels - Math.min(elapsed, MAX_FRAME_SECONDS) * CLEARANCE_SETTLE_PIXELS_PER_SECOND);
		}
		return (int) Math.ceil(reservedPixels);
	}

	void clear()
	{
		reservedPixels = 0;
		holdUntil = 0;
		previousLift = -1;
	}

	/** Returns -1 if lifting cannot safely clear the overhead band inside the viewport. */
	int solve(int minimum, int targetBottom, int left, int top, int right, int bottom,
		IntFunction<Bounds> project)
	{
		if (targetBottom <= top || right <= left || bottom <= top || minimum > MAX_CLEARANCE_LIFT)
		{
			return previousLift = -1;
		}
		int high = Math.max(minimum, previousLift);
		Bounds bounds = project.apply(high);
		if (bounds == null && high != minimum)
		{
			high = minimum;
			bounds = project.apply(high);
		}
		int low = high;
		int step = CLEARANCE_SEARCH_STEP;
		while (bounds != null && bounds.bottom > targetBottom && high < MAX_CLEARANCE_LIFT)
		{
			low = high;
			high = Math.min(MAX_CLEARANCE_LIFT, high + step);
			step *= 2;
			bounds = project.apply(high);
		}
		if (bounds == null || bounds.bottom > targetBottom)
		{
			return previousLift = -1;
		}
		if (low == high)
		{
			// Validate against this frame's projection, then check downward to avoid retaining excess padding.
			// An unchanged scene needs just the previous height and the unit immediately below it.
			step = 1;
			while (low > minimum)
			{
				low = Math.max(minimum, low - step);
				Bounds candidate = project.apply(low);
				if (candidate == null) return previousLift = -1;
				if (candidate.bottom > targetBottom) break;
				high = low;
				bounds = candidate;
				step *= 2;
			}
		}
		while (high - low > 1)
		{
			int mid = (high + low) / 2;
			Bounds candidate = project.apply(mid);
			if (candidate == null) return previousLift = -1;
			if (candidate.bottom > targetBottom) low = mid;
			else
			{
				high = mid;
				bounds = candidate;
			}
		}
		if (bounds.top < top || bounds.bottom > bottom || bounds.left < left || bounds.right > right)
		{
			return previousLift = -1;
		}
		return previousLift = high;
	}

	static Bounds bounds(Client client, LocalPoint location, int centerZ, int radius, int halfHeight)
	{
		int left = Integer.MAX_VALUE, top = Integer.MAX_VALUE;
		int right = Integer.MIN_VALUE, bottom = Integer.MIN_VALUE;
		for (int x = -1; x <= HINT_DISTANCE_TILES; x += 2)
		{
			for (int y = -1; y <= HINT_DISTANCE_TILES; y += 2)
			{
				for (int z = -1; z <= HINT_DISTANCE_TILES; z += 2)
				{
					Point point = Perspective.localToCanvas(client, location.getWorldView(),
						location.getX() + x * radius, location.getY() + y * radius, centerZ + z * halfHeight);
					if (point == null) return null;
					left = Math.min(left, point.getX());
					right = Math.max(right, point.getX());
					top = Math.min(top, point.getY());
					bottom = Math.max(bottom, point.getY());
				}
			}
		}
		return new Bounds(left, top, right, bottom);
	}

	static class Bounds
	{
		final int left, top, right, bottom;

		Bounds(int left, int top, int right, int bottom)
		{
			this.left = left;
			this.top = top;
			this.right = right;
			this.bottom = bottom;
		}
	}
}

package com.escapecrystalnotify;

import java.awt.Color;
import net.runelite.api.Perspective;
import static com.escapecrystalnotify.EscapeCrystalNotifyConfig.Crystal3dDisplayStyle;
import static com.escapecrystalnotify.EscapeCrystalNotifyConfig.Crystal3dFillMode;

final class EscapeCrystalNotifyCrystalDefaults
{
	private EscapeCrystalNotifyCrystalDefaults() {}

	// User-facing defaults.
	static final boolean DEFAULT_ENABLED = false;
	static final boolean DEFAULT_SECTION_CLOSED = true;
	static final boolean DEFAULT_DISPLAY_EVERYWHERE = false;
	static final Crystal3dDisplayStyle DEFAULT_DISPLAY_STYLE = Crystal3dDisplayStyle.ABOVE_HEAD;
	static final Color DEFAULT_ACTIVE_COLOR = new Color(50, 205, 50);
	static final Color DEFAULT_INACTIVE_COLOR = new Color(205, 50, 50);
	static final Crystal3dFillMode DEFAULT_FILL_MODE = Crystal3dFillMode.INACTIVITY_TIME;
	static final int DEFAULT_SIZE = 100;
	static final int DEFAULT_HEIGHT = 60;
	static final int DEFAULT_SPIN_SECONDS = 6;
	static final int DEFAULT_BOB_HEIGHT = 8;
	static final boolean DEFAULT_AUTOMATIC_CLEARANCE = true;
	static final int DEFAULT_CLEARANCE_PADDING = 4;
	static final int DEFAULT_SIDE_OFFSET = 56;
	static final int DEFAULT_FORWARD_OFFSET = 0;
	static final int DEFAULT_SIDE_HEIGHT = 20;

	// Config limits.
	static final int MIN_SIZE = 25, MAX_SIZE = 200;
	static final int MIN_HEIGHT = 0, MAX_HEIGHT = 300;
	static final int MIN_SPIN_SECONDS = 0, MAX_SPIN_SECONDS = 30;
	static final int MIN_BOB_HEIGHT = 0, MAX_BOB_HEIGHT = 30;
	static final int MIN_PADDING = 0, MAX_PADDING = 100;
	static final int MIN_SIDE_OFFSET = -Perspective.LOCAL_TILE_SIZE, MAX_SIDE_OFFSET = Perspective.LOCAL_TILE_SIZE;
	static final int MIN_SIDE_HEIGHT = -100, MAX_SIDE_HEIGHT = 300;

	// Model and motion tuning. Full-turn angle units and tile size come from RuneLite.
	static final double SMALL_STYLE_SCALE = 0.4;
	static final float MODEL_WIDTH_RATIO = 0.4f;
	static final double COLOR_BRIGHTNESS = 1.0;
	static final long MODEL_RETRY_NANOS = 1_000_000_000L;
	static final double MAX_FRAME_SECONDS = 0.1;
	static final double BOB_PERIOD_SECONDS = 3;
	static final int FULL_TURN = Perspective.SINEF.length;

	// Overhead clearance tuning.
	static final long CLEARANCE_HOLD_NANOS = 2_000_000_000L;
	static final int MAX_CLEARANCE_LIFT = 2048;
	static final int VIEWPORT_EDGE_MARGIN = 4;
	static final int HEAD_ANCHOR_OFFSET = 15;
	static final int HEALTH_PIXELS = 32, SKULL_PIXELS = 28, PRAYER_PIXELS = 28, HINT_PIXELS = 32, CHAT_PIXELS = 40;
	static final int HINT_DISTANCE_TILES = 1;
	static final int CLEARANCE_SETTLE_PIXELS_PER_SECOND = 40;
	static final int CLEARANCE_SEARCH_STEP = 32;

	// Fill shading tuning.
	static final double EMPTY_BRIGHTNESS = 0.2;
	static final double FILL_TRANSITION_WIDTH = 0.4;
	static final int MIN_FACE_LIGHTNESS = 2;
}

package com.escapecrystalnotify;

import com.google.common.primitives.Doubles;
import net.runelite.api.Model;
import net.runelite.api.JagexColor;
import static com.escapecrystalnotify.EscapeCrystalNotifyCrystalDefaults.*;

class EscapeCrystalNotifyCrystalFill
{
	private final Model model;
	private final int[] base1, base2, base3;
	private final float[] height;
	private final double[] brightness;
	private double previousFraction = 1;

	EscapeCrystalNotifyCrystalFill(Model model)
	{
		this.model = model;
		base1 = model.getFaceColors1().clone();
		base2 = model.getFaceColors2().clone();
		base3 = model.getFaceColors3().clone();
		float[] y = model.getVerticesY();
		height = new float[model.getVerticesCount()];
		brightness = new double[height.length];
		float min = Float.POSITIVE_INFINITY, max = Float.NEGATIVE_INFINITY;
		for (int i = 0; i < height.length; i++)
		{
			min = Math.min(min, y[i]);
			max = Math.max(max, y[i]);
		}
		for (int i = 0; i < height.length; i++)
		{
			// Model Y is downward: 0 at the bottom tip, 1 at the top tip.
			height[i] = max == min ? 0.5f : (max - y[i]) / (max - min);
		}
	}

	static double fraction(boolean carried, boolean active, int remainingTicks, int totalTicks)
	{
		return carried && active ? fraction(remainingTicks, totalTicks) : 1;
	}

	static double fraction(int remaining, int maximum)
	{
		return maximum <= 0 ? 1 : Doubles.constrainToRange(remaining / (double) maximum, 0, 1);
	}

	void apply(double fraction)
	{
		fraction = Doubles.constrainToRange(fraction, 0, 1);
		if (fraction == previousFraction) return;
		previousFraction = fraction;
		int[] colors1 = model.getFaceColors1(), colors2 = model.getFaceColors2(), colors3 = model.getFaceColors3();
		if (fraction == 1)
		{
			System.arraycopy(base1, 0, colors1, 0, base1.length);
			System.arraycopy(base2, 0, colors2, 0, base2.length);
			System.arraycopy(base3, 0, colors3, 0, base3.length);
			return;
		}
		int[] face1 = model.getFaceIndices1(), face2 = model.getFaceIndices2(), face3 = model.getFaceIndices3();
		double fillTop = fraction * (1 + FILL_TRANSITION_WIDTH);
		for (int i = 0; i < height.length; i++)
		{
			brightness[i] = EMPTY_BRIGHTNESS + (1 - EMPTY_BRIGHTNESS)
				* Doubles.constrainToRange((fillTop - height[i]) / FILL_TRANSITION_WIDTH, 0, 1);
		}
		for (int i = 0; i < model.getFaceCount(); i++)
		{
			if (base3[i] == -2) continue; // Hidden faces stay hidden.
			boolean flat = base3[i] == -1;
			// Gouraud corner colors give the existing mesh a soft fill transition without changing its shape.
			colors1[i] = shade(base1[i], brightness[face1[i]]);
			colors2[i] = shade(flat ? base1[i] : base2[i], brightness[face2[i]]);
			colors3[i] = shade(flat ? base1[i] : base3[i], brightness[face3[i]]);
		}
	}

	private static int shade(int color, double brightness)
	{
		int lightness = Math.max(MIN_FACE_LIGHTNESS, (int) Math.round((color & JagexColor.LUMINANCE_MAX) * brightness));
		return (color & ~JagexColor.LUMINANCE_MAX) | lightness;
	}
}

package com.escapecrystalnotify;

import net.runelite.api.coords.LocalPoint;
import net.runelite.api.Perspective;
import static com.escapecrystalnotify.EscapeCrystalNotifyCrystalDefaults.FULL_TURN;

/** Character-relative offsets in scene units; camera rotation and zoom never move this anchor. */
class EscapeCrystalNotifyCrystalSidePosition
{
	static LocalPoint position(LocalPoint origin, int orientation, int side, int forward)
	{
		// Actor angles: 0 = south, 512 = west, 1024 = north, 1536 = east.
		int angle = orientation & (FULL_TURN - 1);
		double sin = Perspective.SINEF[angle], cos = Perspective.COSINEF[angle];
		int dx = (int) Math.round(-side * cos - forward * sin);
		int dy = (int) Math.round(side * sin - forward * cos);
		return new LocalPoint(origin.getX() + dx, origin.getY() + dy, origin.getWorldView());
	}
}

package com.escapecrystalnotify;

import java.util.Arrays;
import java.util.Comparator;
import java.util.EnumSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;

/** Panel metadata only; entrance detection continues to use the existing region definitions. */
final class EscapeCrystalNotifyEncounters {
    private static final Map<EscapeCrystalNotifyRegionEntrance, EscapeCrystalNotifyRegion> ENTRANCES = new IdentityHashMap<>();
    private static final Set<EscapeCrystalNotifyRegion> WITH_ENTRANCE = EnumSet.noneOf(EscapeCrystalNotifyRegion.class);
    private static final List<EscapeCrystalNotifyRegion> ALL = Arrays.stream(EscapeCrystalNotifyRegion.values())
        .filter(EscapeCrystalNotifyEncounters::supported).map(EscapeCrystalNotifyEncounters::canonical).distinct()
        .sorted(Comparator.comparing(EscapeCrystalNotifyRegion::getRegionName)).collect(Collectors.toUnmodifiableList());
    static {
        for (EscapeCrystalNotifyRegion region : EscapeCrystalNotifyRegion.values()) {
            if (supported(region) && region.getRegionEntrance() != null) {
                ENTRANCES.put(region.getRegionEntrance(), canonical(region));
                if (!region.getRegionEntrance().isEscapeCrystalDisabled() && region.getRegionEntrance().getOverlayType().canHighlight()) {
                    WITH_ENTRANCE.add(canonical(region));
                }
            }
        }
    }

    static boolean supported(EscapeCrystalNotifyRegion region) {
        return region.getRegionType() == EscapeCrystalNotifyRegionType.BOSSES
            || region.getRegionType() == EscapeCrystalNotifyRegionType.RAIDS;
    }

    static EscapeCrystalNotifyRegion canonical(EscapeCrystalNotifyRegion region) {
        switch (region) {
            case BOSS_GAUNTLET_LOBBY:
            case BOSS_CORRUPTED_GAUNTLET: return EscapeCrystalNotifyRegion.BOSS_GAUNTLET;
            case RAIDS_OSMUMTENS_BURIAL_CHAMBER: return EscapeCrystalNotifyRegion.RAIDS_TOMBS_OF_AMASCUT;
            default:
                return region.name().endsWith("_ENTRANCE")
                    ? EscapeCrystalNotifyRegion.valueOf(region.name().replaceFirst("_ENTRANCE$", "")) : region;
        }
    }

    static List<EscapeCrystalNotifyRegion> all() {
        return ALL;
    }

    static EscapeCrystalNotifyRegion forEntrance(EscapeCrystalNotifyRegionEntrance entrance) {
        return ENTRANCES.get(entrance);
    }

    static boolean hasEntrance(EscapeCrystalNotifyRegion region) {
        return WITH_ENTRANCE.contains(canonical(region));
    }

