import java.awt.image.AffineTransformOp;
import java.awt.image.BufferedImage;

public class EscapeCrystalNotifyOverlayActive extends Overlay {
    private static final EscapeCrystalImage previouslyGeneratedImage = new EscapeCrystalImage();
    private static BufferedImage escapeCrystalImage;
    private final EscapeCrystalNotifyPlugin plugin;
    private final EscapeCrystalNotifyConfig config;

    @Inject
    EscapeCrystalNotifyOverlayActive(EscapeCrystalNotifyPlugin plugin, EscapeCrystalNotifyConfig config) throws PluginInstantiationException {
        super(plugin);
        setPriority(OverlayPriority.MED);
        setPosition(OverlayPosition.BOTTOM_LEFT);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);

        this.plugin = plugin;
        this.config = config;

        escapeCrystalImage = loadEscapeCrystalImage();

        initializePreviouslyGeneratedImage();
    }

    private static BufferedImage loadEscapeCrystalImage() {
        return ImageUtil.loadImageResource(EscapeCrystalNotifyPlugin.class, "/escape-crystal-active.png");
    }

    private void initializePreviouslyGeneratedImage() {
        previouslyGeneratedImage.scale = -1;
        previouslyGeneratedImage.generatedImage = escapeCrystalImage;
    }
    @Override
    public Dimension render(Graphics2D graphics) {
        boolean enabled = config.enableOnScreenWidget();
        boolean active = plugin.isEscapeCrystalInactivityTeleportActive();
        boolean notHardcore = config.requireHardcoreAccountType() && !plugin.isHardcoreAccountType();
        boolean inactiveOnly = config.onlyDisplayInactiveOnScreenWidget();
        boolean atSafeRegion = plugin.isAtSafeRegionId();

        boolean atNotifyRegion;

        if (this.plugin.isAtNotifyRegionId()) {
            atNotifyRegion = true;
        } else {
            atNotifyRegion = this.config.alwaysDisplayOnScreenWidget();
        }

        if (!enabled || notHardcore || !atNotifyRegion || !active || inactiveOnly || atSafeRegion) {
            return null;
        }

        BufferedImage generatedEscapeCrystalImage = generateEscapeCrystalImage();
        ImageComponent imagePanelComponent = new ImageComponent(generatedEscapeCrystalImage);
        return imagePanelComponent.render(graphics);
    }

    private BufferedImage generateEscapeCrystalImage() {
        double targetScale = Math.max(config.activeCrystalWidgetScale(), 1);

        boolean escapeCrystalImageScaleChanged = previouslyGeneratedImage.scale != targetScale;
        boolean escapeCrystalLeftClickTeleportEnabledChanged = previouslyGeneratedImage.escapeCrystalLeftClickTeleportEnabled != plugin.isEscapeCrystalLeftClickTeleportEnabled();
        boolean escapeCrystalInactivityTicksChanged = previouslyGeneratedImage.escapeCrystalInactivityTicks != plugin.getEscapeCrystalInactivityTicks();
        boolean expectedServerInactivityTicksChanged = previouslyGeneratedImage.expectedServerInactivityTicks != plugin.getExpectedServerInactivityTicks();

        if (!escapeCrystalInactivityTicksChanged && !expectedServerInactivityTicksChanged && !escapeCrystalImageScaleChanged && !escapeCrystalLeftClickTeleportEnabledChanged) {
            return previouslyGeneratedImage.generatedImage;
        }

        BufferedImage scaledEscapeCrystalImage;
        if (!escapeCrystalImageScaleChanged) {
            scaledEscapeCrystalImage = previouslyGeneratedImage.scaledBaseImage;
        } else {
            scaledEscapeCrystalImage = scaleImage(escapeCrystalImage, targetScale / 5);
        }

        String overlayText = determineActiveEscapeCrystalOverlayText();
        boolean displayLeftClickWarning = !plugin.isEscapeCrystalLeftClickTeleportEnabled() && config.displayDisabledLeftClickTeleportText();
        BufferedImage generatedEscapeCrystalImage = drawInfoTextOnImage(scaledEscapeCrystalImage, targetScale, overlayText, displayLeftClickWarning);

        previouslyGeneratedImage.scaledBaseImage = scaledEscapeCrystalImage;
        previouslyGeneratedImage.generatedImage = generatedEscapeCrystalImage;
        previouslyGeneratedImage.scale = targetScale;
        previouslyGeneratedImage.escapeCrystalLeftClickTeleportEnabled = plugin.isEscapeCrystalLeftClickTeleportEnabled();
        previouslyGeneratedImage.escapeCrystalInactivityTicks = plugin.getEscapeCrystalInactivityTicks();
        previouslyGeneratedImage.expectedServerInactivityTicks = plugin.getExpectedServerInactivityTicks();

        return generatedEscapeCrystalImage;
    }

    private BufferedImage scaleImage(BufferedImage image, double scale) {
        BufferedImage scaledImage = new BufferedImage(
                (int) (scale * image.getWidth()),
                (int) (scale * image.getHeight()),
                BufferedImage.TYPE_INT_ARGB
        );

        AffineTransform at = new AffineTransform();
        at.scale(scale, scale);
        AffineTransformOp scaleOp = new AffineTransformOp(at, AffineTransformOp.TYPE_BILINEAR);
        scaledImage = scaleOp.filter(image, scaledImage);

        return scaledImage;
    }

    private String determineActiveEscapeCrystalOverlayText() {
        return plugin.getItemModelDisplayText(config.onScreenWidgetDisplayFormat(), config.onScreenWidgetInactivityTimeFormat(), config.onScreenWidgetTimeExpiredText());
    }

    private BufferedImage drawInfoTextOnImage(BufferedImage image, double scale, String overlayText, boolean addLeftClickWarning) {
        BufferedImage imageWithInfoText = new BufferedImage(image.getWidth(), image.getHeight(), image.getType());

        Graphics g = imageWithInfoText.getGraphics();
        g.drawImage(image, 0, 0, null);

        int fontSize;
        if (overlayText.length() >= 4) {
            fontSize = 5;
        } else {
            fontSize = 6;
        }

        Font font = new Font("Arial", Font.BOLD, fontSize * (int) Math.ceil(scale));

        g.setFont(font);
        g.setColor(Color.BLACK);
        drawTextLowerFourth(g, font, overlayText, imageWithInfoText.getWidth() + 1, imageWithInfoText.getHeight() + 1);

        g.setColor(plugin.getItemModelDisplayTextColor(config.onScreenWidgetDisplayFormat()));

        drawTextLowerFourth(g, font, overlayText, imageWithInfoText.getWidth() - 1, imageWithInfoText.getHeight() - 1);

        if (addLeftClickWarning){
            Font warningMessageFont = new Font("Arial", Font.BOLD, (int) (2.5 * Math.ceil(scale)));
            g.setFont(warningMessageFont);
            g.setColor(Color.RED);
            FontMetrics metrics = g.getFontMetrics(warningMessageFont);
            drawTextBottomMiddle(g, warningMessageFont, "NO LEFT", imageWithInfoText.getWidth(), imageWithInfoText.getHeight() - metrics.getHeight());
            drawTextBottomMiddle(g, warningMessageFont, "CLICK", imageWithInfoText.getWidth(), imageWithInfoText.getHeight());
        }

        g.dispose();

        return imageWithInfoText;
    }

    private void drawTextLowerFourth(Graphics g, Font font, String text, int x, int y) {
        FontMetrics metrics = g.getFontMetrics(font);

        int textWidth = metrics.stringWidth(text);
        int textAscent = metrics.getAscent();
        int textDescent = metrics.getDescent();

        int xDrawLocation = (x - textWidth) / 2;
        int yDrawLocation = y - (textAscent + (y - (textAscent + textDescent)) / 4);

        g.drawString(text, xDrawLocation, yDrawLocation);
    }

    private void drawTextBottomMiddle(Graphics g, Font font, String text, int x, int y) {
        FontMetrics metrics = g.getFontMetrics(font);
        int textWidth = metrics.stringWidth(text);
        int xDrawLocation = (x - textWidth) / 2;
        g.drawString(text, xDrawLocation, y);
    }

    private static class EscapeCrystalImage {
        private double scale;
        private BufferedImage scaledBaseImage;
        private BufferedImage generatedImage;
        private boolean escapeCrystalLeftClickTeleportEnabled;
        private int escapeCrystalInactivityTicks;
        private int expectedServerInactivityTicks;


    }
}

package com.escapecrystalnotify;

import net.runelite.client.plugins.PluginInstantiationException;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import java.awt.*;
import java.awt.geom.AffineTransform;
import java.awt.image.AffineTransformOp;
import java.awt.image.BufferedImage;

public class EscapeCrystalNotifyOverlayInactive extends Overlay {
    private static final EscapeCrystalImage previouslyGeneratedImage = new EscapeCrystalImage();
    private static BufferedImage escapeCrystalImage;
    private final EscapeCrystalNotifyPlugin plugin;
    private final EscapeCrystalNotifyConfig config;

    @Inject
    EscapeCrystalNotifyOverlayInactive(EscapeCrystalNotifyPlugin plugin, EscapeCrystalNotifyConfig config) throws PluginInstantiationException {
        super(plugin);
        setPriority(OverlayPriority.LOW);
        setPosition(OverlayPosition.BOTTOM_LEFT);
        setLayer(OverlayLayer.ABOVE_SCENE);

        this.plugin = plugin;
        this.config = config;

        escapeCrystalImage = loadEscapeCrystalImage();

        initializePreviouslyGeneratedImage();
    }

    private static BufferedImage loadEscapeCrystalImage() {
        return ImageUtil.loadImageResource(EscapeCrystalNotifyPlugin.class, "/escape-crystal-inactive.png");
    }

    private void initializePreviouslyGeneratedImage() {
        previouslyGeneratedImage.scale = 1;
        previouslyGeneratedImage.generatedImage = escapeCrystalImage;
    }
    @Override
    public Dimension render(Graphics2D graphics) {
        boolean enabled = config.enableOnScreenWidget();
        boolean active = plugin.isEscapeCrystalInactivityTeleportActive();
        boolean notHardcore = config.requireHardcoreAccountType() && !plugin.isHardcoreAccountType();
        boolean atSafeRegion = plugin.isAtSafeRegionId();

        boolean atNotifyRegion;
        if (this.plugin.isAtNotifyRegionId()) {
            atNotifyRegion = true;
        } else {
            atNotifyRegion = this.config.alwaysDisplayOnScreenWidget();
        }

        if (!enabled || notHardcore || !atNotifyRegion || active || atSafeRegion) {
            return null;
        }

        BufferedImage generatedEscapeCrystalImage = generateEscapeCrystalImage();
        ImageComponent imagePanelComponent = new ImageComponent(generatedEscapeCrystalImage);
        return imagePanelComponent.render(graphics);
    }

    private BufferedImage generateEscapeCrystalImage() {
        double targetScale = Math.max(config.inactiveCrystalWidgetScale(), 1);
        boolean escapeCrystalImageScaleChanged = previouslyGeneratedImage.scale != targetScale;

        if (!escapeCrystalImageScaleChanged) {
            return previouslyGeneratedImage.generatedImage;
        }

        BufferedImage generatedEscapeCrystalImage = scaleImage(escapeCrystalImage, targetScale / 5);

        previouslyGeneratedImage.generatedImage = generatedEscapeCrystalImage;
        previouslyGeneratedImage.scale = targetScale;

        return generatedEscapeCrystalImage;
    }

    private BufferedImage scaleImage(BufferedImage image, double scale) {
        BufferedImage scaledImage = new BufferedImage(
                (int) (scale * image.getWidth()),
                (int) (scale * image.getHeight()),
                BufferedImage.TYPE_INT_ARGB
        );

        AffineTransform at = new AffineTransform();
        at.scale(scale, scale);
        AffineTransformOp scaleOp = new AffineTransformOp(at, AffineTransformOp.TYPE_BILINEAR);
        scaledImage = scaleOp.filter(image, scaledImage);

        return scaledImage;
    }

    private static class EscapeCrystalImage {
        private double scale;
        private BufferedImage generatedImage;

    }
}

package com.escapecrystalnotify;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.text.ParseException;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.BiConsumer;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.text.DefaultFormatter;
import javax.swing.text.DefaultFormatterFactory;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;

final class EscapeCrystalNotifyPanel extends PluginPanel {
    private final EscapeCrystalNotifyThresholds thresholds;
    private final Map<String, EncounterRow> rows = new LinkedHashMap<>();
    private final Map<EscapeCrystalNotifyRegionType, JLabel> headings = new EnumMap<>(EscapeCrystalNotifyRegionType.class);
    private final Map<EscapeCrystalNotifyRegionType, JPanel> sections = new EnumMap<>(EscapeCrystalNotifyRegionType.class);
    private final JPanel nearbyRows = createRowContainer();
    private final JLabel nearbyEmpty = new JLabel("No supported entrances nearby");
    private Set<EscapeCrystalNotifyRegion> nearbyBosses = Collections.emptySet();
    private final JLabel noMatches = new JLabel("No matching encounters");
    private boolean refreshing;
    private Object displayedProfile;
    private String lastQuery = "";

    EscapeCrystalNotifyPanel(EscapeCrystalNotifyThresholds thresholds, BiConsumer<Integer, JLabel> loadIcon) {
        this.thresholds = thresholds;
        addHeader();
        addSearchField();
        addNearbySection();
        addEncounterSection(EscapeCrystalNotifyRegionType.BOSSES, "Bosses", loadIcon);
        addEncounterSection(EscapeCrystalNotifyRegionType.RAIDS, "Raids", loadIcon);
        noMatches.setVisible(false);
        add(noMatches);
        refresh();
    }

    private void addHeader() {
        add(new JLabel("<html><div style='width:150px'><b>Maximum crystal settings</b><br>All values are in seconds.</div></html>"));
    }

    private void addSearchField() {
        JLabel searchLabel = new JLabel("Search bosses and raids");
        searchLabel.setBorder(new EmptyBorder(8, 0, 0, 0));
        IconTextField search = new IconTextField();
        search.setIcon(IconTextField.Icon.SEARCH);
        search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        search.setBorder(new EmptyBorder(7, 0, 7, 0));
        searchLabel.setLabelFor(search);
        add(searchLabel);
        add(search);
        search.getDocument().addDocumentListener(new DocumentListener() {
            @Override public void insertUpdate(DocumentEvent e) { filter(search.getText()); }
            @Override public void removeUpdate(DocumentEvent e) { filter(search.getText()); }
            @Override public void changedUpdate(DocumentEvent e) { filter(search.getText()); }
        });
    }

    private void addEncounterSection(EscapeCrystalNotifyRegionType type, String title, BiConsumer<Integer, JLabel> loadIcon) {
        JLabel heading = new JLabel(title);
        heading.setBorder(new EmptyBorder(12, 0, 4, 0));
        headings.put(type, heading);
        add(heading);
        JPanel section = createRowContainer();
        sections.put(type, section);
        add(section);
        for (EscapeCrystalNotifyRegion encounter : EscapeCrystalNotifyEncounters.all()) {
            if (encounter.getRegionType() != type) continue;
            EncounterRow row = new EncounterRow(encounter, loadIcon);
            rows.put(row.key, row);
            section.add(row);
        }
    }

    private static JPanel createRowContainer() {
        JPanel container = new JPanel(new DynamicGridLayout(0, 1, 0, 3));
        container.setOpaque(false);
        return container;
    }

    private void addNearbySection() {
        JLabel heading = new JLabel("Nearby");
        heading.setBorder(new EmptyBorder(12, 0, 4, 0));
        add(heading);
        nearbyRows.setVisible(false);
        add(nearbyRows);
        nearbyEmpty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        add(nearbyEmpty);
    }

    void setNearbyBosses(Set<EscapeCrystalNotifyRegion> nearby) {
        if (nearbyBosses.equals(nearby)) return;
        nearbyBosses = Set.copyOf(nearby);
        int nearbyIndex = 0;
        int bossIndex = 0;
        int raidIndex = 0;
        for (EncounterRow row : rows.values()) {
            boolean isNearby = nearbyBosses.contains(row.encounter);
            JPanel parent = isNearby ? nearbyRows : sections.get(row.encounter.getRegionType());
            int index = isNearby ? nearbyIndex++ : row.encounter.getRegionType() == EscapeCrystalNotifyRegionType.BOSSES
                ? bossIndex++ : raidIndex++;
            if (row.getParent() != parent) parent.add(row);
            parent.setComponentZOrder(row, index);
        }
        applyFilter();
    }

    private void filter(String text) {
        String query = text.trim().toLowerCase(Locale.ROOT);
        if (query.equals(lastQuery)) return;
        lastQuery = query;
        applyFilter();
    }

    private void applyFilter() {
        boolean bossesVisible = false;
        boolean raidsVisible = false;
        boolean nearbyVisible = false;
        for (EncounterRow row : rows.values()) {
            boolean visible = row.searchName.contains(lastQuery);
            row.setVisible(visible);
            if (visible) {
                if (nearbyBosses.contains(row.encounter)) nearbyVisible = true;
                else if (row.encounter.getRegionType() == EscapeCrystalNotifyRegionType.BOSSES) bossesVisible = true;
                else raidsVisible = true;
            }
        }
        headings.get(EscapeCrystalNotifyRegionType.BOSSES).setVisible(bossesVisible);
        headings.get(EscapeCrystalNotifyRegionType.RAIDS).setVisible(raidsVisible);
        sections.get(EscapeCrystalNotifyRegionType.BOSSES).setVisible(bossesVisible);
        sections.get(EscapeCrystalNotifyRegionType.RAIDS).setVisible(raidsVisible);
        nearbyRows.setVisible(nearbyVisible);
        nearbyEmpty.setText(nearbyBosses.isEmpty() ? "No supported entrances nearby" : "No nearby matches");
        nearbyEmpty.setVisible(!nearbyVisible);
        noMatches.setVisible(!bossesVisible && !raidsVisible && !nearbyVisible);
        revalidate();
        repaint();
    }

    private boolean ensureCurrentProfile() {
        if (displayedProfile == thresholds.profile()) return true;
        refresh();
        return false;
    }

    void refresh() {
        refresh(null);
    }

    void refresh(String key) {
        Object profile = thresholds.profile();
        boolean refreshAll = key == null || displayedProfile != profile;
        refreshing = true;
        try {
            displayedProfile = profile;
            if (refreshAll) {
                rows.values().forEach(row -> row.refresh(true));
            } else {
                EncounterRow row = rows.get(key);
                if (row != null) row.refresh(false);
            }
        } finally {
            refreshing = false;
        }
    }

    private final class EncounterRow extends JPanel {
        private final EscapeCrystalNotifyRegion encounter;
        private final String key;
        private final String searchName;
        private final JSpinner spinner;
        private final JFormattedTextField input;

        private EncounterRow(EscapeCrystalNotifyRegion encounter, BiConsumer<Integer, JLabel> loadIcon) {
            super(new BorderLayout(6, 0));
            this.encounter = encounter;
            key = EscapeCrystalNotifyThresholds.key(encounter);
            searchName = encounter.getRegionName().toLowerCase(Locale.ROOT);
            setBackground(ColorScheme.DARKER_GRAY_COLOR);
            setBorder(new EmptyBorder(8, 6, 8, 8));
            spinner = EscapeCrystalNotifyEncounters.hasEntrance(encounter) ? createSpinner() : null;
            input = spinner == null ? null : ((JSpinner.NumberEditor) spinner.getEditor()).getTextField();
            if (input != null) configureInput();
            add(createIcon(loadIcon), BorderLayout.WEST);
            add(createDetails(), BorderLayout.CENTER);
        }

        private JLabel createIcon(BiConsumer<Integer, JLabel> loadIcon) {
            JLabel icon = new JLabel();
            icon.setPreferredSize(new Dimension(36, 32));
            loadIcon.accept(EscapeCrystalNotifyEncounters.icon(encounter), icon);
            return icon;
        }

        private JPanel createDetails() {
            JPanel details = new JPanel(new BorderLayout(0, 6));
            details.setOpaque(false);
            details.add(wrappedLabel(encounter.getRegionName()), BorderLayout.NORTH);
            if (spinner != null) {
                details.add(createEditor(), BorderLayout.CENTER);
            } else {
                JLabel unavailable = wrappedLabel("Entrance warning unavailable");
                unavailable.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
                details.add(unavailable, BorderLayout.CENTER);
            }
            return details;
        }

        private JLabel wrappedLabel(String text) {
            return new JLabel("<html><div style='width:112px'>" + text + "</div></html>");
        }

        private JSpinner createSpinner() {
            JSpinner spinner = new JSpinner(new SpinnerNumberModel(EscapeCrystalNotifyThresholdDefaults.seconds(encounter),
                EscapeCrystalNotifyThresholds.MIN_SECONDS, Integer.MAX_VALUE, 1));
            spinner.setEditor(new JSpinner.NumberEditor(spinner, "0"));
            spinner.setPreferredSize(new Dimension(68, 24));
            return spinner;
        }

        private void configureInput() {
            input.setFormatterFactory(new DefaultFormatterFactory(new DefaultFormatter() {
                @Override public Object stringToValue(String text) throws ParseException {
                    try {
                        return EscapeCrystalNotifyThresholds.parseSeconds(text);
                    } catch (NumberFormatException e) {
                        throw new ParseException("Enter whole seconds, at least " + EscapeCrystalNotifyThresholds.MIN_SECONDS, 0);
                    }
                }
            }));
            ((DefaultFormatter) input.getFormatter()).setOverwriteMode(false);
            input.setFocusLostBehavior(JFormattedTextField.PERSIST);
            input.setToolTipText("Maximum inactivity setting in seconds (minimum: " + EscapeCrystalNotifyThresholds.MIN_SECONDS
                + ", default: " + EscapeCrystalNotifyThresholdDefaults.seconds(encounter) + ")");
            input.addActionListener(e -> commit());
            input.addFocusListener(new FocusAdapter() {
                @Override public void focusLost(FocusEvent e) { commit(); }
            });
            spinner.addChangeListener(e -> save());
        }

        private JPanel createEditor() {
            JPanel editor = new JPanel(new BorderLayout(8, 0));
            editor.setOpaque(false);
            editor.add(spinner, BorderLayout.WEST);
            JButton reset = new JButton("Reset");
            reset.setMargin(new Insets(0, 2, 0, 2));
            reset.setBorderPainted(false);
            reset.setContentAreaFilled(false);
            reset.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            reset.setToolTipText("Reset to " + EscapeCrystalNotifyThresholdDefaults.seconds(encounter) + " seconds");
            reset.addActionListener(e -> resetToDefault());
            editor.add(reset, BorderLayout.EAST);
            return editor;
        }

        private void save() {
            if (!refreshing && ensureCurrentProfile()) {
                thresholds.set(encounter, (Integer) spinner.getValue(), displayedProfile);
            }
        }

        private void resetToDefault() {
            if (!ensureCurrentProfile()) return;
            spinner.setValue(EscapeCrystalNotifyThresholdDefaults.seconds(encounter));
            input.setValue(spinner.getValue());
        }

        private void commit() {
            if (refreshing || !ensureCurrentProfile()) return;
            try {
                spinner.commitEdit();
            } catch (ParseException | IllegalArgumentException e) {
                input.setValue(spinner.getValue());
            }
        }

        private void refresh(boolean force) {
            if (spinner == null) return;
            int value = thresholds.get(encounter);
            if (force || !spinner.getValue().equals(value)) {
                spinner.setValue(value);
                input.setValue(value);
            }
        }
    }
}

package com.escapecrystalnotify;

import java.awt.AlphaComposite;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;

/** Removes visible player faces from the ground effect's private drawing buffer. */
final class EscapeCrystalNotifyPlayerMask
{
	private int[] screenX = new int[0], screenY = new int[0];
	private final Polygon triangle = new Polygon(new int[3], new int[3], 3);

	void erase(Graphics2D graphics, Client client, Player player, LocalPoint location, int height, Rectangle bounds)
	{
		Model model = player.getModel();
		if (model == null) return;
		int count = model.getVerticesCount();
		if (screenX.length < count)
		{
			screenX = new int[count];
			screenY = new int[count];
		}
		Perspective.modelToCanvas(client, player.getWorldView(), count, location.getX(), location.getY(),
			height, player.getCurrentOrientation(), model.getVerticesX(), model.getVerticesZ(), model.getVerticesY(), screenX, screenY);
		eraseFaces(graphics, model, screenX, screenY, bounds);
	}

	void eraseFaces(Graphics2D graphics, Model model, int[] x, int[] y, Rectangle bounds)
	{
		int[] first = model.getFaceIndices1(), second = model.getFaceIndices2(), third = model.getFaceIndices3();
		byte[] transparency = model.getFaceTransparencies();
		graphics.setComposite(AlphaComposite.Clear);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		for (int face = 0; face < model.getFaceCount(); face++)
		{
			if (transparency != null && (transparency[face] & 255) >= 254) continue;
			int a = first[face], b = second[face], c = third[face];
			if (x[a] == Integer.MIN_VALUE || x[b] == Integer.MIN_VALUE || x[c] == Integer.MIN_VALUE) continue;
			long direction = (long) (x[b] - x[a]) * (y[c] - y[a]) - (long) (y[b] - y[a]) * (x[c] - x[a]);
			if (direction >= 0) continue;
			int left = Math.min(x[a], Math.min(x[b], x[c])), right = Math.max(x[a], Math.max(x[b], x[c]));
			int top = Math.min(y[a], Math.min(y[b], y[c])), bottom = Math.max(y[a], Math.max(y[b], y[c]));
			if (!bounds.intersects(left, top, right - left, bottom - top)) continue;
			triangle.xpoints[0] = x[a]; triangle.ypoints[0] = y[a];
			triangle.xpoints[1] = x[b]; triangle.ypoints[1] = y[b];
			triangle.xpoints[2] = x[c]; triangle.ypoints[2] = y[c];
			triangle.invalidate();
			graphics.fill(triangle);
		}
	}
}

package com.escapecrystalnotify;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class EscapeCrystalNotifyPlayerOutlineOverlay extends Overlay
{
	private final EscapeCrystalNotifyGroundCircle groundCircle = new EscapeCrystalNotifyGroundCircle();
	private final Client client;
	private final EscapeCrystalNotifyPlugin plugin;
	private final EscapeCrystalNotifyConfig config;
	private final ModelOutlineRenderer outlines;

	@Inject
	EscapeCrystalNotifyPlayerOutlineOverlay(Client client, EscapeCrystalNotifyPlugin plugin,
		EscapeCrystalNotifyConfig config, ModelOutlineRenderer outlines)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	Color outlineColor()
	{
		return indicatorColor(config.enablePlayerOutline(), config.alwaysDisplayPlayerOutline(),
			config.playerOutlineActiveColor(), config.playerOutlineInactiveColor());
	}

	Color circleColor()
	{
		return indicatorColor(config.enablePlayerCircle(), config.alwaysDisplayPlayerCircle(),
			config.playerCircleActiveColor(), config.playerCircleInactiveColor());
	}

	private Color indicatorColor(boolean enabled, boolean everywhere, Color active, Color inactive)
	{
		if (!enabled || !plugin.isAccountTypeEnabled()
			|| (!everywhere && !plugin.isAtNotifyRegionId())) return null;
		return plugin.isEscapeCrystalInactivityTeleportActive()
			? active : inactive;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Color outline = outlineColor(), circle = circleColor();
		if (!isVisible(outline) && !isVisible(circle)) return null;
		Player player = client.getLocalPlayer();
		if (player != null)
		{
			if (isVisible(circle))
			{
				drawGroundCircle(graphics, player, circle);
			}
			if (isVisible(outline))
			{
				outlines.drawOutline(player, config.playerOutlineWidth(), outline, config.playerOutlineFeather());
			}
		}
		return null;
	}

	private static boolean isVisible(Color color)
	{
		return color != null && color.getAlpha() != 0;
	}

	private void drawGroundCircle(Graphics2D graphics, Player player, Color color)
	{
		LocalPoint location = player.getLocalLocation();
		if (location == null || player.getWorldView() == null) return;
		groundCircle.draw(graphics, client, location, player.getWorldView().getPlane(), color,
			config.playerCircleWidth(), config.groundCircleGlow(), config.playerCircleDisplay(), player);
	}
}

