	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!config.enableTeleportNpc() || event.getActor() != client.getLocalPlayer()) return;
		Player player = client.getLocalPlayer();
		if (player == null) return;
		if (player.getAnimation() != AnimationID.HUMAN_CASTTELEPORT)
		{
			teleportNpc.reset();
			return;
		}
		if (teleportDuration == 0)
		{
			Animation animation = client.loadAnimation(AnimationID.HUMAN_CASTTELEPORT);
			if (animation == null) return;
			teleportDuration = animation.isMayaAnim() ? animation.getNumFrames()
				: Arrays.stream(animation.getFrameLengths()).sum();
		}
		teleportNpc.spawnHidden(player, client.getGameCycle() + teleportDuration);
		if (isDebugModeEnabled() && config.debugTeleportNpcOnAnyTeleport()) teleportNpc.show();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id != InventoryID.INVENTORY.getId() && id != InventoryID.EQUIPMENT.getId()) return;
		ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		int count = inventory == null || equipment == null ? -1
			: inventory.count(ItemID.TOB_TELEPORT) + equipment.count(ItemID.TOB_TELEPORT);
		if (count != crystalCount)
		{
			// An increase cancels a pending reveal when a crystal moves between containers.
			revealTeleportNpc = crystalCount >= 0 && count >= 0 && count < crystalCount;
		}
		crystalCount = count;
	}


	@Subscribe
	public void onMenuOpened(MenuOpened event) {
		addFixConfirmationMenuEntry(event);
		if (!config.showSetCrystalMaximumOption() || validEntrances.isEmpty()) return;
		Set<EscapeCrystalNotifyRegion> added = new HashSet<>();
		for (EscapeCrystalNotifyLocatedEntrance entrance : validEntrances) {
			EscapeCrystalNotifyRegion encounter = EscapeCrystalNotifyEncounters.forEntrance(entrance.getDefinition());
			if (encounter == null || added.contains(encounter)) continue;
			for (MenuEntry entry : event.getMenuEntries()) {
				NPC npc = entry.getNpc();
				int entryId = npc != null ? npc.getId() : entry.getIdentifier();
				if (entryId != entrance.getTarget().getId()) continue;
				// Only add this after right-click opens the menu; preserve normal left-click and safeguards.
				client.createMenuEntry(1).setOption("Set crystal maximum")
					.setTarget(ColorUtil.wrapWithColorTag(encounter.getRegionName(), Color.ORANGE))
					.setType(MenuAction.RUNELITE).onClick(e -> openThresholdInput(encounter));
				added.add(encounter);
				break;
			}
		}
	}

	private void addFixConfirmationMenuEntry(MenuOpened event) {
		if (escapeCrystalNotifyTextOverlayPanel == null
			|| (!isLeviathanSafeguardPanelEnabled() && !isDoomSafeguardPanelEnabled())) return;
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		if (!escapeCrystalNotifyTextOverlayPanel.getBounds().contains(mouse.getX(), mouse.getY())) return;

		for (OverlayMenuEntry fixEntry : escapeCrystalNotifyTextOverlayPanel.getMenuEntries()) {
			// RuneLite already adds overlay actions when Shift is held.
			boolean alreadyAdded = Arrays.stream(event.getMenuEntries()).anyMatch(entry ->
				fixEntry.getOption().equals(entry.getOption())
					&& fixEntry.getTarget().equals(Text.removeTags(entry.getTarget())));
			if (!alreadyAdded) {
				client.createMenuEntry(1).setOption(fixEntry.getOption())
					.setTarget(ColorUtil.wrapWithColorTag(fixEntry.getTarget(), Color.ORANGE))
					.setType(fixEntry.getMenuAction())
					.onClick(entry -> onOverlayMenuClicked(new OverlayMenuClicked(fixEntry, escapeCrystalNotifyTextOverlayPanel)));
			}
		}
	}

	void openThresholdInput(EscapeCrystalNotifyRegion encounter) {
		Object editedProfile = thresholds.profile();
		chatboxPanelManager.openTextInput(encounter.getRegionName() + ": maximum crystal setting (whole seconds, at least " + EscapeCrystalNotifyThresholds.MIN_SECONDS + ")")
			.value(Integer.toString(thresholds.get(encounter)))
			.onDone((Predicate<String>) text -> saveThresholdInput(encounter, text, editedProfile)).build();
	}

	boolean saveThresholdInput(EscapeCrystalNotifyRegion encounter, String text, Object editedProfile) {
		try {
			thresholds.set(encounter, EscapeCrystalNotifyThresholds.parseSeconds(text), editedProfile);
			return true;
		} catch (NumberFormatException e) {
			return false; // Keep the input open so invalid values can be corrected.
		}
	}

	@Subscribe(priority = -2)
	public void onPostMenuSort(PostMenuSort e) {
		boolean inLeviathanEncounter = this.isLeviathanSafeguardEnabled() && this.atLeviathanRegionId && !this.atLeviathanLobby;
		boolean inDoomEncounter = this.isDoomSafeguardEnabled() && this.atDoomRegionId && !this.atDoomLobby && !this.doomFloorCleared;

		if (inLeviathanEncounter || inDoomEncounter) {
			deprioritizeLogoutButton();
		}

		deprioritizeEnterOption();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject spawnedObject = event.getGameObject();
		int spawnedObjectId = spawnedObject.getId();

		boolean debugEntrance = !this.gameObjectEntranceIds.contains(spawnedObjectId)
			&& isDebugEntranceObjectId(spawnedObjectId);
		if (this.gameObjectEntranceIds.contains(spawnedObjectId) || debugEntrance) {
			WorldPoint locatedWorldPoint = resolvePossiblyInstancedWorldPoint(spawnedObject.getWorldLocation(), spawnedObject.getLocalLocation());
			EscapeCrystalNotifyRegionEntrance definition = EscapeCrystalNotifyRegion.findEntrance(
				spawnedObjectId, locatedWorldPoint, EscapeCrystalNotifyRegionEntranceObjectType.GAME_OBJECT);

			if (ENTRANCE_CLEAR_REQUIRED_IDS.contains(spawnedObjectId)) {
				clearPossibleEntranceId(spawnedObjectId);
			}

			addPossibleEntrance(locatedWorldPoint.getRegionID(),
					new EscapeCrystalNotifyLocatedEntrance(
							new EscapeCrystalNotifyRegionEntranceObject(spawnedObject),
							debugEntrance ? new EscapeCrystalNotifyRegionEntrance(spawnedObjectId, true) : definition,
							locatedWorldPoint,
							spawnedObjectId
					)
			);
		}

		if (!this.doomRegionIds.contains(this.currentRegionId)) return;

        if (DOOM_BURROW_HOLE_IDS.contains(spawnedObjectId)) this.doomFloorCleared = true;
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject despawnedObject = event.getGameObject();

		if (this.gameObjectEntranceIds.contains(despawnedObject.getId()) || isDebugEntranceObjectId(despawnedObject.getId())) {
			WorldPoint locatedWorldPoint = resolvePossiblyInstancedWorldPoint(despawnedObject.getWorldLocation(), despawnedObject.getLocalLocation());
			int regionId = locatedWorldPoint.getRegionID();
			List<EscapeCrystalNotifyLocatedEntrance> entrances = possibleEntrances.get(regionId);

			if (ENTRANCE_CLEAR_REQUIRED_IDS.contains(despawnedObject.getId())) {
				clearPossibleEntranceId(despawnedObject.getId());
			}

			if (entrances != null) {
				entrances.removeIf(entrance ->
					entrance.getTarget().getId() == despawnedObject.getId());

				if (entrances.isEmpty()) {
					possibleEntrances.remove(regionId);
				}
			}
		}

		// Special handling for Leviathan boat despawning as a different ID
		else if (despawnedObject.getId() == net.runelite.api.gameval.ObjectID.DT2_SCAR_BOAT_ISLAND) {
			possibleEntrances.remove(8292);
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned npc)
	{
		NPC spawnedNpc = npc.getNpc();
		int spawnedNpcId = spawnedNpc.getId();

		boolean debugEntrance = !this.npcEntranceIds.contains(spawnedNpcId)
			&& isDebugEntranceNpcId(spawnedNpcId);
		if (this.npcEntranceIds.contains(spawnedNpcId) || debugEntrance) {
			WorldPoint locatedWorldPoint = resolvePossiblyInstancedWorldPoint(spawnedNpc.getWorldLocation(), spawnedNpc.getLocalLocation());
			EscapeCrystalNotifyRegionEntrance definition = EscapeCrystalNotifyRegion.findEntrance(
				spawnedNpcId, locatedWorldPoint, EscapeCrystalNotifyRegionEntranceObjectType.NPC);

			if (!debugEntrance && this.infernoEntranceRegionIds.contains(locatedWorldPoint.getRegionID())) {
				for (int regionId : this.infernoEntranceRegionIds) {
					addPossibleEntrance(regionId,
							new EscapeCrystalNotifyLocatedEntrance(
									new EscapeCrystalNotifyRegionEntranceObject(spawnedNpc),
									definition,
									locatedWorldPoint,
									spawnedNpcId
							)
					);
				}
			} else if (!debugEntrance && spawnedNpcId == NpcID.WHISPERER_SPAWN) {
				for (int regionId : this.whispererEntranceRegionIds) {
					addPossibleEntrance(regionId,
							new EscapeCrystalNotifyLocatedEntrance(
									new EscapeCrystalNotifyRegionEntranceObject(spawnedNpc),
									EscapeCrystalNotifyRegion.BOSS_THE_WHISPERER.getRegionEntrance(),
									locatedWorldPoint,
									spawnedNpcId
							)
					);
				}
			} else if (!debugEntrance && spawnedNpcId == NpcID.DT2_PURSUER_HIDEOUT_COMBAT) {
				this.clearPossibleEntranceId(ObjectID.DT2_HIDEOUT_ALTAR_OP);
			} else {
				addPossibleEntrance(locatedWorldPoint.getRegionID(),
						new EscapeCrystalNotifyLocatedEntrance(
								new EscapeCrystalNotifyRegionEntranceObject(spawnedNpc),
								debugEntrance ? new EscapeCrystalNotifyRegionEntrance(spawnedNpcId, true) : definition,
								locatedWorldPoint,
								spawnedNpcId
						)
				);
			}
		}

		if (!this.doomRegionIds.contains(this.currentRegionId)) {
			this.doomFloorCleared = true;
			return;
		}
		if (DOOM_NPC_IDS.contains(spawnedNpcId)) this.doomFloorCleared = false;
	}

