package com.escapecrystalnotify;

import net.runelite.api.MenuAction;
import net.runelite.client.plugins.PluginInstantiationException;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import org.apache.commons.lang3.StringUtils;

import javax.inject.Inject;
import java.awt.*;


public class EscapeCrystalNotifyTextOverlayPanel extends OverlayPanel {
    static final String CONFIRM_FIX_OPTION = "Confirm fix";
    static final String LEVIATHAN_FIX_TARGET = "Leviathan logout bug";
    static final String DOOM_FIX_TARGET = "Doom logout bug";
    private static final String FIX_INSTRUCTION_TEXT = "Right-click this panel and select 'Confirm fix' to hide this notice. Enable 'Display Fix Info' in the safeguard settings to show it again.";
    private static final String LEVIATHAN_FIX_INFO_TEXT = "The Leviathan logout bug has been fixed. Safeguards are now disabled by default and remain available as an optional setting.";
    private static final String DOOM_FIX_INFO_TEXT = "The Doom of Mokhaiotl logout bug has been fixed. Safeguards are now disabled by default and remain available as an optional setting.";
    private static final Font OVERLAY_PANEL_FONT = FontManager.getRunescapeSmallFont();
    private static final int OVERLAY_PANEL_WIDTH = 235;
    private static final int OVERLAY_PANEL_HEIGHT = 100;
    private static final String SIX_HOUR_WARNING_TEXT = "WARNING: You are approaching the 6-hour forced logout timer! You should re-log to avoid a potential forced death";
    private static final String LEVIATHAN_BUG_INFO_HEADER_TEXT = "WARNING: LEVIATHAN BUG";
    private static final String LEVIATHAN_BUG_INFO_TEXT = "Attempting to logout during the encounter can/will DISABLE ALL PLAYER ACTIONS (teleports, prayers, food, etc...) and cause an UNAVOIDABLE DEATH";
    private static final String LEVIATHAN_LOGOUT_STATUS_DEPRIORITIZED_TEXT_SHORT = "Right-Click Required";
    private static final String LEVIATHAN_LOGOUT_STATUS_HEADER_TEXT = "Current Logout Setting:";
    private static final String LEVIATHAN_LOGOUT_STATUS_PRIORITIZED_TEXT_SHORT = "Left-Click";
    private static final String LEVIATHAN_LOGOUT_STATUS_PRIORITIZED_TEXT_SHORT_ADDITIONAL_INFO = "NOT PROTECTED";
    private static final String LEVIATHAN_INSTRUCTION_TEXT = "Navigate to the 'Leviathan Safeguards' section in the 'Escape Crystal Notify' settings to enable left-click logout prevention and/or hide this panel";
    private static final String DOOM_BUG_INFO_HEADER_TEXT = "WARNING: DOOM BUG";
    private static final String DOOM_BUG_INFO_TEXT = "Attempting to logout during the encounter can/will DISABLE ALL PLAYER ACTIONS (teleports, prayers, food, etc...) and cause an UNAVOIDABLE DEATH";
    private static final String DOOM_LOGOUT_STATUS_DEPRIORITIZED_TEXT_SHORT = "Right-Click Required";
    private static final String DOOM_LOGOUT_STATUS_DEPRIORITIZED_TEXT_ADDITIONAL_INFO = "Left-Click enabled between floors";
    private static final String DOOM_LOGOUT_STATUS_HEADER_TEXT = "Current Logout Setting:";
    private static final String DOOM_LOGOUT_STATUS_PRIORITIZED_TEXT_SHORT = "Left-Click";
    private static final String DOOM_LOGOUT_STATUS_PRIORITIZED_TEXT_SHORT_ADDITIONAL_INFO = "NOT PROTECTED";
    private static final String DOOM_INSTRUCTION_TEXT = "Navigate to the 'Doom Safeguards' section in the 'Escape Crystal Notify' settings to enable left-click logout prevention and/or hide this panel";

    private final EscapeCrystalNotifyPlugin plugin;
    private final EscapeCrystalNotifyConfig config;

    @Inject
    EscapeCrystalNotifyTextOverlayPanel(EscapeCrystalNotifyPlugin plugin, EscapeCrystalNotifyConfig config) throws PluginInstantiationException {
        super(plugin);

        setPosition(OverlayPosition.TOP_RIGHT);
        setPriority(OverlayPriority.HIGH);

        this.plugin = plugin;
        this.config = config;
    }
    @Override
    public Dimension render(Graphics2D graphics) {
        getMenuEntries().clear();
        panelComponent.getChildren().clear();
        if (!plugin.isLeviathanSafeguardPanelEnabled() && !plugin.isDoomSafeguardPanelEnabled()) return null;

        String bugInfoHeaderText = null;
        String bugInfoText = null;
        String logoutStatusHeaderText = null;
        String logoutStatusText = null;
        String logoutStatusAdditionalText = null;
        Color logoutStatusTextColor = null;
        String sixHourWarningText = null;
        String instructionText = null;
        String fixInfoText = null;

        if (plugin.isLeviathanSafeguardPanelEnabled()) {
            boolean modeEnabled = config.leviathanLogoutSafeguardMode() != EscapeCrystalNotifyConfig.SafeguardAccountType.DISABLED;
            if (modeEnabled && config.displayLeviathanBugInfo()) {
                bugInfoHeaderText = LEVIATHAN_BUG_INFO_HEADER_TEXT;
                bugInfoText = LEVIATHAN_BUG_INFO_TEXT;
                instructionText = LEVIATHAN_INSTRUCTION_TEXT;
            }

            if (config.displayLeviathanFixInfo()) {
                fixInfoText = LEVIATHAN_FIX_INFO_TEXT;
                if (bugInfoHeaderText == null) bugInfoHeaderText = "LEVIATHAN BUG FIXED";
                instructionText = FIX_INSTRUCTION_TEXT;
                addMenuEntry(MenuAction.RUNELITE_OVERLAY, CONFIRM_FIX_OPTION, LEVIATHAN_FIX_TARGET);
            }

            if (modeEnabled && config.displayLeviathanLogoutSetting()) {
                logoutStatusHeaderText = LEVIATHAN_LOGOUT_STATUS_HEADER_TEXT;

                if (plugin.isLeviathanSafeguardEnabled()) {
                    logoutStatusText = LEVIATHAN_LOGOUT_STATUS_DEPRIORITIZED_TEXT_SHORT;
                    logoutStatusTextColor = Color.GREEN;
                } else {
                    logoutStatusText = LEVIATHAN_LOGOUT_STATUS_PRIORITIZED_TEXT_SHORT;
                    logoutStatusAdditionalText = LEVIATHAN_LOGOUT_STATUS_PRIORITIZED_TEXT_SHORT_ADDITIONAL_INFO;
                    logoutStatusTextColor = JagexColors.CHAT_FC_TEXT_TRANSPARENT_BACKGROUND;
                }
            };

            if (plugin.isLeviathanSixHourWarningEnabled()
                    && plugin.isCloseToLeviathanSixHourLogout()) sixHourWarningText = SIX_HOUR_WARNING_TEXT;
        } else if (plugin.isDoomSafeguardPanelEnabled()) {
            boolean modeEnabled = config.doomLogoutSafeguardMode() != EscapeCrystalNotifyConfig.SafeguardAccountType.DISABLED;
            if (modeEnabled && config.displayDoomBugInfo()) {
                bugInfoHeaderText = DOOM_BUG_INFO_HEADER_TEXT;
                bugInfoText = DOOM_BUG_INFO_TEXT;
                instructionText = DOOM_INSTRUCTION_TEXT;
            }

            if (config.displayDoomFixInfo()) {
                fixInfoText = DOOM_FIX_INFO_TEXT;
                if (bugInfoHeaderText == null) bugInfoHeaderText = "DOOM BUG FIXED";
                instructionText = FIX_INSTRUCTION_TEXT;
                addMenuEntry(MenuAction.RUNELITE_OVERLAY, CONFIRM_FIX_OPTION, DOOM_FIX_TARGET);
            }

            if (modeEnabled && config.displayDoomLogoutSetting()) {
                logoutStatusHeaderText = DOOM_LOGOUT_STATUS_HEADER_TEXT;

                if (plugin.isDoomSafeguardEnabled()) {
                    logoutStatusText = DOOM_LOGOUT_STATUS_DEPRIORITIZED_TEXT_SHORT;
                    logoutStatusAdditionalText = DOOM_LOGOUT_STATUS_DEPRIORITIZED_TEXT_ADDITIONAL_INFO;
                    logoutStatusTextColor = Color.GREEN;
                } else {
                    logoutStatusText = DOOM_LOGOUT_STATUS_PRIORITIZED_TEXT_SHORT;
                    logoutStatusAdditionalText = DOOM_LOGOUT_STATUS_PRIORITIZED_TEXT_SHORT_ADDITIONAL_INFO;
                    logoutStatusTextColor = JagexColors.CHAT_FC_TEXT_TRANSPARENT_BACKGROUND;
                }
            }

            if (plugin.isDoomSixHourWarningEnabled()
                    && plugin.isCloseToDoomSixHourLogout()) sixHourWarningText = SIX_HOUR_WARNING_TEXT;
        } else {
            return null;
        }

        final FontMetrics metrics = graphics.getFontMetrics(OVERLAY_PANEL_FONT);

        LineComponent newLineComponent = LineComponent.builder().left("\n").build();

        panelComponent.setPreferredSize(new Dimension(OVERLAY_PANEL_WIDTH, OVERLAY_PANEL_HEIGHT));
        panelComponent.getChildren().clear();

        if (bugInfoHeaderText != null) {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left(getCenteredText(bugInfoHeaderText, metrics))
                    .leftFont(OVERLAY_PANEL_FONT)
                    .leftColor(JagexColors.YELLOW_INTERFACE_TEXT)
                    .build());
        }

        if (bugInfoText != null) {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left(bugInfoText)
                    .leftFont(OVERLAY_PANEL_FONT)
                    .leftColor(JagexColors.YELLOW_INTERFACE_TEXT)
                    .build());
        }

        if (fixInfoText != null) {
            if (bugInfoText != null) panelComponent.getChildren().add(newLineComponent);
            panelComponent.getChildren().add(LineComponent.builder()
                    .left(fixInfoText)
                    .leftFont(OVERLAY_PANEL_FONT)
                    .leftColor(JagexColors.YELLOW_INTERFACE_TEXT)
                    .build());
        }

        if (logoutStatusHeaderText != null) {
            if (!panelComponent.getChildren().isEmpty()) {
                panelComponent.getChildren().add(newLineComponent);
            }

            LineComponent.LineComponentBuilder logoutStatusComponent = LineComponent.builder()
                    .left(logoutStatusHeaderText)
                    .leftColor(JagexColors.DARK_ORANGE_INTERFACE_TEXT)
                    .leftFont(OVERLAY_PANEL_FONT);

            logoutStatusComponent
                    .right(logoutStatusText)
                    .rightColor(logoutStatusTextColor)
                    .rightFont(OVERLAY_PANEL_FONT);

            panelComponent.getChildren().add(logoutStatusComponent.build());

            if (logoutStatusAdditionalText != null) {
                panelComponent.getChildren().add(LineComponent.builder()
                        .right(logoutStatusAdditionalText)
                        .rightFont(OVERLAY_PANEL_FONT)
                        .rightColor(logoutStatusTextColor)
                        .build());
            }
        }

        if (sixHourWarningText != null) {
            if (!panelComponent.getChildren().isEmpty()) {
                panelComponent.getChildren().add(newLineComponent);
            }

            panelComponent.getChildren().add(LineComponent.builder()
                    .left(SIX_HOUR_WARNING_TEXT)
                    .leftFont(OVERLAY_PANEL_FONT)
                    .leftColor(JagexColors.CHAT_FC_TEXT_TRANSPARENT_BACKGROUND)
                    .build());
        }

        if (instructionText != null) {
            if (!panelComponent.getChildren().isEmpty()) {
                panelComponent.getChildren().add(newLineComponent);
            }

            panelComponent.getChildren().add(LineComponent.builder()
                    .left(instructionText)
                    .leftFont(OVERLAY_PANEL_FONT)
                    .leftColor(JagexColors.YELLOW_INTERFACE_TEXT)
                    .build());
        }

        return panelComponent.render(graphics);
    }

    private static String getCenteredText(String text, FontMetrics metrics) {
        int spaceWidth = metrics.stringWidth(" ");
        int remainingWidth = OVERLAY_PANEL_WIDTH - metrics.stringWidth(text);
        int requiredSpaces = remainingWidth / spaceWidth;
        int characterCount = text.length() + requiredSpaces;
        return StringUtils.center(text, characterCount);
    }
}

package com.escapecrystalnotify;

import java.util.function.BiConsumer;
import java.util.function.Function;
import java.util.function.Supplier;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

/** Reads through to RuneLite so overlay and menu checks always use the active profile. */
final class EscapeCrystalNotifyThresholds {
    static final String PREFIX = "maximumSeconds_";
    static final int MIN_SECONDS = 2;
    private final Function<String, String> read;
    private final BiConsumer<String, Integer> write;
    private final Supplier<Object> profile;

    @Inject
    EscapeCrystalNotifyThresholds(ConfigManager configManager) {
        this(key -> configManager.getConfiguration(EscapeCrystalNotifyConfig.GROUP, key),
            (key, value) -> configManager.setConfiguration(EscapeCrystalNotifyConfig.GROUP, key, value), configManager::getProfile);
    }

    EscapeCrystalNotifyThresholds(Function<String, String> read, BiConsumer<String, Integer> write, Supplier<Object> profile) {
        this.read = read;
        this.write = write;
        this.profile = profile;
    }

    Object profile() { return profile.get(); }

    int get(EscapeCrystalNotifyRegion encounter) {
        String saved = read.apply(key(encounter));
        if (saved == null || saved.trim().isEmpty()) return EscapeCrystalNotifyThresholdDefaults.seconds(encounter);
        try {
            return parseSeconds(saved);
        } catch (NumberFormatException e) {
            return EscapeCrystalNotifyThresholdDefaults.seconds(encounter);
        }
    }

    void set(EscapeCrystalNotifyRegion encounter, int seconds, Object editedProfile) {
        if (seconds >= MIN_SECONDS && editedProfile == profile()) {
            write.accept(key(encounter), seconds);
        }
    }

    static int parseSeconds(String text) {
        if (text == null || !text.trim().matches("[0-9]+")) throw new NumberFormatException();
        int seconds = Integer.parseInt(text.trim());
        if (seconds < MIN_SECONDS) throw new NumberFormatException();
        return seconds;
    }

    static String key(EscapeCrystalNotifyRegion encounter) {
        return PREFIX + EscapeCrystalNotifyEncounters.canonical(encounter).name();
    }
}

package com.escapecrystalnotify;

import java.lang.reflect.Proxy;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class EscapeCrystalNotifyClosestEntranceTest {
    private final WorldView view = proxy(WorldView.class, (n, a) -> null);
    private final Player player = proxy(Player.class, (n, a) -> n.equals("getWorldView") ? view
        : n.equals("getWorldLocation") ? new WorldPoint(6400, 6400, 0) : null);
    private final Client client = proxy(Client.class, (n, a) -> n.equals("getLocalPlayer") ? player : null);

    @Test
    public void defaultsOffAndSupportsFluentOptIn() {
        EscapeCrystalNotifyRegionEntrance definition = definition();
        assertFalse(definition.isClosest());
        assertSame(definition, definition.withClosest());
        assertTrue(definition.isClosest());
    }

    @Test
    public void selectsUsingWorldPointDistanceAndPreservesFirstTie() {
        EscapeCrystalNotifyRegionEntrance definition = definition().withClosest();
        EscapeCrystalNotifyLocatedEntrance diagonal = entrance(definition, 4, 4, 0, view);
        EscapeCrystalNotifyLocatedEntrance straight = entrance(definition, 5, 0, 0, view);
        EscapeCrystalNotifyLocatedEntrance tie = entrance(definition, 0, 4, 0, view);
        assertEquals(List.of(diagonal), select(straight, diagonal, tie));
    }

    @Test
    public void excludesCloserCopyOnOtherPlaneOrInOtherWorldView() {
        EscapeCrystalNotifyRegionEntrance definition = definition().withClosest();
        EscapeCrystalNotifyLocatedEntrance upstairs = entrance(definition, 0, 0, 1, view);
        EscapeCrystalNotifyLocatedEntrance otherView = entrance(definition, 0, 0, 0, proxy(WorldView.class, (n, a) -> null));
        EscapeCrystalNotifyLocatedEntrance valid = entrance(definition, 10, 10, 0, view);
        assertEquals(List.of(valid), select(upstairs, otherView, valid));
        assertTrue(select(upstairs, otherView).isEmpty());
    }

    @Test
    public void selectsPerIdAndLeavesUnflaggedEntrancesAlone() {
        EscapeCrystalNotifyRegionEntrance first = definition().withClosest(), second = definition().withClosest();
        second.entranceIds = new int[]{2};
        EscapeCrystalNotifyRegionEntrance normal = definition();
        EscapeCrystalNotifyLocatedEntrance a = entrance(first, 2, 2, 0, view);
        EscapeCrystalNotifyLocatedEntrance b = entrance(second, 8, 8, 0, view);
        EscapeCrystalNotifyLocatedEntrance c = entrance(normal, 0, 0, 1, view);
        EscapeCrystalNotifyLocatedEntrance d = entrance(normal, 9, 9, 0, view);
        assertEquals(List.of(a, b, c, d), select(a, b, c, d));
    }

    @Test
    public void replacesByIdAcrossDefinitionsWithoutMovingOtherEntries() {
        EscapeCrystalNotifyLocatedEntrance far = entrance(definition().withClosest(), 8, 8, 0, view);
        EscapeCrystalNotifyLocatedEntrance normal = entrance(definition(), 6, 6, 0, view);
        EscapeCrystalNotifyLocatedEntrance near = entrance(definition().withClosest(), 1, 1, 0, view);
        assertEquals(List.of(near, normal), select(far, normal, near));
    }

    @Test
    public void invalidCloserCopyDoesNotReplaceEligibleEntrance() {
        EscapeCrystalNotifyRegionEntrance invalid = definition().withClosest();
        invalid.chunkIds = List.of(-1);
        EscapeCrystalNotifyLocatedEntrance near = entrance(invalid, 1, 1, 0, view);
        EscapeCrystalNotifyLocatedEntrance far = entrance(definition().withClosest(), 8, 8, 0, view);
        assertEquals(List.of(far), select(near, far));
    }

    @Test
    public void missingPlayerOnlyRemovesFlaggedEntrances() {
        EscapeCrystalNotifyLocatedEntrance a = entrance(definition().withClosest(), 1, 1, 0, view);
        EscapeCrystalNotifyLocatedEntrance b = entrance(definition(), 2, 2, 0, view);
        assertEquals(List.of(b), selectWithClient(null, a, b));
    }

    @Test
    public void supportsNpcEntranceAndChecksItsPlane() {
        EscapeCrystalNotifyRegionEntrance definition = definition().withClosest();
        for (int plane = 0; plane <= 1; plane++) {
            WorldPoint point = new WorldPoint(6401, 6401, plane);
            NPC npc = proxy(NPC.class, (n, a) -> n.equals("getWorldView") ? view : n.equals("getWorldLocation") ? point : null);
            EscapeCrystalNotifyLocatedEntrance entrance = new EscapeCrystalNotifyLocatedEntrance(
                new EscapeCrystalNotifyRegionEntranceObject(npc), definition, point, 1);
            assertEquals(plane == 0 ? List.of(entrance) : List.of(), select(entrance));
        }
    }

    private EscapeCrystalNotifyRegionEntrance definition() {
        return new EscapeCrystalNotifyRegionEntrance(EscapeCrystalNotifyRegionEntranceOverlayType.DEPRIORITIZED_WITH_HIGHLIGHT,
            null, EscapeCrystalNotifyRegionEntranceObjectType.ANY, 1);
    }

    private EscapeCrystalNotifyLocatedEntrance entrance(EscapeCrystalNotifyRegionEntrance definition, int x, int y, int plane, WorldView targetView) {
        WorldPoint point = new WorldPoint(6400 + x, 6400 + y, plane);
        GameObject object = proxy(GameObject.class, (n, a) -> {
            switch (n) {
                case "getWorldView": return targetView;
                case "getWorldLocation": return point;
                case "getPlane": return plane;
                case "getId": return definition.getEntranceIds()[0];
                default: return null;
            }
        });
        EscapeCrystalNotifyRegionEntranceObject target = new EscapeCrystalNotifyRegionEntranceObject(object) {
            @Override public WorldPoint getWorldLocation() {
                return new WorldPoint(3200, 3200, 0);
            }
        };
        return new EscapeCrystalNotifyLocatedEntrance(target, definition, target.getWorldLocation(), definition.getEntranceIds()[0]);
    }

    private List<EscapeCrystalNotifyLocatedEntrance> select(EscapeCrystalNotifyLocatedEntrance... entries) {
        return selectWithClient(client, entries);
    }

    private List<EscapeCrystalNotifyLocatedEntrance> selectWithClient(Client selectedClient, EscapeCrystalNotifyLocatedEntrance... entries) {
        try {
            EscapeCrystalNotifyPlugin plugin = new EscapeCrystalNotifyPlugin();
            set(plugin, "client", selectedClient);
            set(plugin, "atNotifyRegionId", true);
            set(plugin, "possibleEntrances", Map.of(1, Arrays.asList(entries)));
            java.lang.reflect.Method compute = EscapeCrystalNotifyPlugin.class.getDeclaredMethod("computeEntranceObjectMetrics");
            compute.setAccessible(true);
            compute.invoke(plugin);
            return plugin.getValidEntrances();
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }

    private static void set(Object target, String name, Object value) throws ReflectiveOperationException {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private interface Answer { Object get(String name, Object[] args); }
    private static <T> T proxy(Class<T> type, Answer answer) {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (p, m, a) -> {
            Object value = answer.get(m.getName(), a);
            if (value != null) return value;
            if (m.getReturnType() == boolean.class) return false;
            if (m.getReturnType() == int.class) return 0;
            return null;
        }));
    }
}

package com.escapecrystalnotify;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.events.ConfigChanged;
import org.junit.Test;
import static org.junit.Assert.*;

public class EscapeCrystalNotifyConfigRoutingTest
{
	@Test
	public void everyDeclaredConfigKeyRoutesToOnlyItsDependentCaches() throws Exception
	{
		Set<String> regionKeys = Set.of("enableDebugMode", "displayBosses", "displayRaids",
			"displayDungeons", "displayMinigames", "displayTeleportDisabled", "excludeZulrahWithEliteDiary",
			"includeRegionIds", "excludeRegionIds", "debugEntranceObjects", "debugEntranceNpcs");
		Set<String> notificationKeys = Set.of("notifyTimeUntilTeleportThreshold",
			"notificationInactivityTimeFormat", "onScreenWidgetInactivityTimeFormat");
		int checked = 0;
		for (Method method : EscapeCrystalNotifyConfig.class.getDeclaredMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item == null) continue;
			Fixture f = new Fixture();
			f.change(item.keyName());
			assertEquals(item.keyName(), regionKeys.contains(item.keyName()), f.settings.regionReads > 0);
			assertEquals(item.keyName(), notificationKeys.contains(item.keyName()), f.settings.notificationReads > 0);
			checked++;
		}
		assertEquals("Update the audit when config options are added or removed", 127, checked);
	}

	@Test
	public void testingModeRefreshesRegionOverrides() throws Exception
	{
		Fixture f = new Fixture();
		f.change("enableDebugMode");
		assertTrue(f.settings.regionReads > 0);
		assertEquals(0, f.settings.notificationReads);
	}

	@Test
	public void displayChangesDoNotRebuildRegionOrNotificationSettings() throws Exception
	{
		Fixture f = new Fixture();
		for (String key : new String[]{"playerOutlineActiveColor", "enablePlayerOutline",
			"alwaysDisplayPlayerOutline", "requireHardcoreAccountType", "crystal3dSize", "enableCrystal3d",
			"enableTeleportNpc", "teleportNpcType", "debugTeleportNpcOnAnyTeleport", "inventoryActiveFillColor",
			"alwaysDisplayInventory", "enableNonHardcoreInventoryHighlight", "entranceOverlayFillColor"})
		{
			f.change(key);
		}
		assertEquals(0, f.settings.regionReads);
		assertEquals(0, f.settings.notificationReads);
	}

	@Test
	public void dependentSettingsRefreshOnlyTheirOwnCachedValues() throws Exception
	{
		Fixture f = new Fixture();
		f.change("includeRegionIds");
		assertTrue(f.settings.regionReads > 0);
		assertEquals(0, f.settings.notificationReads);
		assertTrue(((java.util.Set<?>) get(f.plugin, "targetRegionIds")).contains(12345));
		int reads = f.settings.regionReads;
		f.change("notifyTimeUntilTeleportThreshold");
		assertTrue(f.settings.notificationReads > 0);
		assertEquals(reads, f.settings.regionReads);
		assertEquals("Your escape crystal will teleport you in 42 ticks!",
			get(f.plugin, "notifyTimeRemainingThresholdMessage"));
	}

	@Test
	public void fullRefreshStillUpdatesAllCachesAndOtherGroupsAreIgnored() throws Exception
	{
		Fixture f = new Fixture();
		ConfigChanged event = new ConfigChanged();
		event.setGroup("anotherPlugin");
		event.setKey("includeRegionIds");
		f.plugin.onConfigChanged(event);
		assertEquals(0, f.settings.regionReads);
		assertEquals(0, f.settings.notificationReads);
		f.plugin.onConfigChanged(null);
		assertTrue(f.settings.regionReads > 0);
		assertTrue(f.settings.notificationReads > 0);
	}

	private static class Settings implements EscapeCrystalNotifyConfig
	{
		int regionReads, notificationReads;
		@Override public boolean displayBosses() { regionReads++; return true; }
		@Override public String includeRegionIds() { return "12345"; }
		@Override public int notifyTimeUntilTeleportThreshold() { notificationReads++; return 42; }
		@Override public InactivityTimeFormat notificationInactivityTimeFormat() { return InactivityTimeFormat.GAME_TICKS; }
	}

	private static class Fixture
	{
		final EscapeCrystalNotifyPlugin plugin = new EscapeCrystalNotifyPlugin();
		final Settings settings = new Settings();
		Fixture() throws Exception
		{
			set(plugin, "config", settings);
		}
		void change(String key)
		{
			ConfigChanged event = new ConfigChanged();
			event.setGroup(EscapeCrystalNotifyConfig.GROUP);
			event.setKey(key);
			plugin.onConfigChanged(event);
		}
	}

	private static Object get(Object target, String name) throws Exception
	{
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		return field.get(target);
	}

	private static void set(Object target, String name, Object value) throws Exception
	{
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}
}

